"""Normalize workbook tables and add an independently written radio glossary."""
import json
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'app/src/main/assets/course.json'
c=json.loads(p.read_text())
if c['formulas'] and isinstance(c['formulas'][0],list):
    c['formulas']=[dict(title=x[0],formula=x[1],note=x[2]) for x in c['formulas']]
if c['bands'] and isinstance(c['bands'][0],list):
    c['bands']=[dict(name=x[0],range=x[1],low=x[2],high=x[3],access=x[4],bandwidth=x[5],note=x[6]) for x in c['bands']]
if c['glossary'] and isinstance(c['glossary'][0],list):
    c['glossary']=[dict(term=x[0],definition=x[1]) for x in c['glossary']]
terms={g['term'].casefold():g for g in c['glossary']}
def add(term,expansion,definition,example='',category='Concepts',lab='',source=''):
    terms[term.casefold()]=dict(term=term,expansion=expansion,definition=definition,example=example,category=category,lab=lab,source=source)
add('VOX','Voice-operated transmit / voice-operated switch','Automatically keys the transmitter when microphone audio passes a threshold. VOX gain or sensitivity sets the trigger level; delay sets how long the transmitter stays on after speech stops.','If room noise keeps keying the radio, reduce VOX sensitivity. Anti-VOX helps stop loudspeaker audio from triggering it.','Radio controls',source='https://www.icomjapan.com/lineup/products/3377/')
add('FM','Frequency modulation','Encodes information by varying the instantaneous frequency of a carrier while its amplitude stays approximately constant. Commonly used for local VHF/UHF voice and repeaters.','Speech changes the frequency deviation. It should not intentionally change the RF envelope amplitude.','Modes','modulation')
add('NFM','Narrow-band frequency modulation','FM configured for a narrower occupied bandwidth than a wider FM setting, usually by reducing frequency deviation and using appropriate audio filtering. It is still analogue FM. Match the channel plan and the other station’s deviation and bandwidth.','An NFM setting may use about ±2.5 kHz deviation on a suitably planned channel, but exact settings depend on the equipment and service. Narrow FM is not the same as turning down the speaker volume.','Modes','modulation')
add('AM','Amplitude modulation','Encodes information by varying a carrier’s amplitude. Conventional AM contains the carrier plus upper and lower sidebands. Too much modulation can cause distortion and unwanted emissions.','Broadcast medium-wave radio commonly uses AM. At 100% modulation, an ideal AM envelope just reaches zero at its minima.','Modes','modulation')
add('CW','Continuous wave','In amateur operation, CW usually means a carrier keyed on and off to send Morse code. The carrier is present during each dot or dash; controlled keying edges limit unwanted bandwidth.','Dots and dashes change how long the carrier is on. CW does not mean ordinary voice on an unmodulated carrier.','Modes','modulation')
add('USB','Upper sideband','A form of single-sideband modulation that keeps the sideband above the nominal suppressed-carrier frequency. Normally the carrier and the lower sideband are suppressed. A receiver must use a compatible mode to reproduce intelligible speech.','A 1 kHz audio tone sent on USB at a nominal carrier of 14.200 MHz appears at 14.201 MHz. Here USB means upper sideband, not Universal Serial Bus.','Modes','modulation')
add('LSB','Lower sideband','A form of single-sideband modulation that keeps the sideband below the nominal suppressed-carrier frequency, with the other sideband and normally the carrier suppressed.','A 1 kHz audio tone on LSB at 7.100 MHz appears at 7.099 MHz.','Modes','modulation')
add('SSB','Single sideband','An amplitude-modulation technique that transmits one sideband while normally suppressing the carrier and the other sideband. USB and LSB are the two choices. It makes efficient use of bandwidth and transmitter power for voice.','Use a compatible USB or LSB receive setting to make an SSB voice signal intelligible.','Modes','modulation')
add('WFM','Wide-band frequency modulation','FM using wider deviation and occupied bandwidth than narrow-band voice FM. It is commonly associated with FM broadcast reception. It is not interchangeable with an amateur narrow FM channel setting.','','Modes','modulation')
add('CTCSS','Continuous Tone-Coded Squelch System','A low-frequency continuous tone sent with an analogue FM signal. A receiver can require the matching tone before opening its speaker, and a repeater can require it for access. It provides neither privacy nor encryption.','A repeater listing might require a 100.0 Hz transmit tone. Tone encode sends it; tone decode requires it on receive.','Access tones','repeater','https://comms.kenwood.com/en/support/glossary/')
add('DCS','Digital / digitally coded squelch','A coded, low-rate digital signal carried with analogue FM audio to control access or receiver squelch. Radios must agree on the code and, where applicable, normal or inverted polarity. DCS does not turn analogue voice into digital voice and does not provide privacy.','D023N identifies a particular DCS code with normal polarity. It is not a 23 Hz CTCSS tone.','Access tones',source='https://comms.kenwood.com/en/support/glossary/')
add('DTCS','Digital Tone Code Squelch','Icom terminology for a digital coded squelch system in the DCS family. Use the correct code and polarity for the equipment involved.','A radio menu may say DTCS where another brand says DCS.','Access tones',source='https://www.icomjapan.com/lineup/products/IC-T10/')
add('OWNID','Own ID / self ID enquiry','A manufacturer-specific label for the radio’s own selective-calling identifier. In the Retevis RT95 manual, OWNID displays the current channel’s DTMF or 5-tone ID. Other radios may use the label differently; check that model’s manual. It is not automatically your amateur call sign or a DMR ID.','If an RT95 menu shows OWNID, it is asking about the programmed selective-calling ID, rather than antenna tuning or receiver gain.','Radio controls',source='https://www.radiomanual.info/schemi/Vari/Retevis_RT-95_user.pdf')
add('Gain','','An increase in a signal level, or an antenna’s directional advantage relative to a stated reference. Amplifier gain describes amplification; antenna gain describes concentration of radiation. Always check whether the number is a power ratio, a voltage ratio, dBi or dBd.','An ideal antenna with 3 dB more gain gives about twice the power density in its main direction for the same applied power. It does not create transmitter power.','Antennas','gain')
add('RF gain','Radio-frequency gain control','Adjusts amplification early in a receiver. Reducing it can help with overload or strong signals; it is different from the speaker volume control.','Turning AF gain down quiets the speaker. Turning RF gain down changes receiver amplification.','Radio controls')
add('AF gain','Audio-frequency gain control','The receiver volume control: it adjusts audio delivered to headphones or a speaker.','Use AF gain for comfortable listening without changing the transmitter’s output.','Radio controls')
add('Microphone gain','','Adjusts how much microphone audio drives the transmitter. Excessive gain can cause distortion, over-deviation or splatter.','Use the transmitter’s meter and the manufacturer’s setup procedure rather than turning the control fully up.','Radio controls')
add('Squelch','','Mutes receiver noise until a signal or matching signalling condition is detected. Setting the threshold too high can hide weak signals.','Carrier squelch responds to signal strength; tone squelch also requires a matching CTCSS or DCS setting.','Radio controls','repeater')
add('PTT','Push to talk','A button or control that changes a transceiver from receiving to transmitting while held.','Press PTT, pause briefly for a repeater to open, then speak clearly.','Radio controls')
add('VFO','Variable-frequency oscillator','Originally an adjustable oscillator; on a modern radio, VFO mode usually means freely tuning a frequency instead of selecting a saved memory channel.','Choose VFO mode to enter a new receive frequency, then save its settings to a memory if desired.','Radio controls')
add('Memory channel','','A saved set of radio settings, usually including receive frequency, transmit frequency or offset, mode and access signalling.','Two memories can have the same frequency but different tone settings.','Radio controls')
add('Offset','','The difference between a radio’s transmit and receive frequencies when using a repeater. Positive offset puts transmit above receive; negative offset puts it below.','146.940 MHz receive with −0.600 MHz offset gives 146.340 MHz transmit.','Operating','repeater')
add('Duplex','','Communication using different transmit and receive frequencies. Full duplex permits simultaneous transmit and receive; a typical handheld repeater user operates half duplex.','The repeater receives its input while transmitting its output.','Operating','repeater')
add('Tone encode / decode','','Encode sends a CTCSS tone or DCS code. Decode requires a matching tone or code before the receiver opens squelch. You may need encode only for repeater access.','If you enable receive tone squelch with the wrong tone, you can miss an otherwise audible repeater.','Access tones','repeater')
add('DTMF','Dual-tone multi-frequency','A signalling method that sends a pair of audio tones for each key. Often used for selective calling or authorized repeater control.','The familiar telephone keypad uses DTMF tones.','Access tones')
add('ANI','Automatic number identification','A signalling feature that sends a programmed unit identifier, often at the beginning or end of a transmission. Its implementation depends on the radio.','An ANI number in programming software and an amateur call sign serve different purposes.','Access tones')
add('5-tone / SelCall','Five-tone selective calling','A sequence of audio tones used to address or identify a particular radio or group. The exact tone plan and code length depend on the system.','A selective-calling ID may be shown under OWNID on some radios.','Access tones')
add('BCL / BCLO','Busy-channel lockout','Inhibits transmission when the radio detects a busy channel according to its programmed rules.','A radio that beeps instead of transmitting may have busy-channel lockout enabled.','Radio controls')
add('TOT','Time-out timer','Limits the duration of one continuous transmission. Release PTT and follow the radio or repeater’s reset behaviour.','A time-out timer can limit an accidentally stuck microphone.','Radio controls')
add('RIT','Receiver incremental tuning','Shifts receive tuning slightly without changing the transmit frequency.','Use RIT to clarify an off-frequency SSB station while keeping your own transmit frequency fixed.','Radio controls')
add('XIT','Transmitter incremental tuning','Shifts transmit tuning slightly while leaving receive tuning unchanged. Exact labels vary by manufacturer.','','Radio controls')
add('SQL','Squelch','A common label for the squelch control in radio menus. It usually changes the threshold needed to unmute received audio.','','Radio controls')
add('NB / NR','Noise blanker / noise reduction','A noise blanker targets certain impulse noise; noise reduction processes received signals to make background noise less distracting. Neither can recover information that has been completely lost.','','Radio controls')
add('ATT','Attenuator','Reduces the signal level entering a receiver. Can improve reception when very strong signals overload it.','','Radio controls')
add('Preamp','Preamplifier','An amplifier placed ahead of later receiver stages to boost weak signals. More preamplification can worsen overload when strong signals are present.','','Radio controls')
add('DSP','Digital signal processing','Mathematical processing of digitized signals for filtering, demodulation, noise reduction and related tasks.','','Electronics')
add('ADC / DAC','Analogue-to-digital / digital-to-analogue converter','An ADC turns sampled analogue signals into digital values. A DAC produces an analogue output from digital values.','','Electronics')
add('SDR','Software-defined radio','A radio in which significant functions such as filtering or demodulation are performed by software. An SDR’s hardware tuning range does not grant permission to transmit.','A receive-only SDR can help you learn to recognize AM, FM and SSB signals.','Modes','modulation')
add('I/Q','In-phase and quadrature','Two signal components separated by a quarter cycle. Together they preserve amplitude and phase information used in SDR processing.','','Electronics')
add('DMR','Digital Mobile Radio','A digital radio standard used in amateur and commercial systems. Amateur configurations commonly use a Radio ID, talkgroup, colour code and time slot.','A DMR Radio ID and an ISED call sign are different identifiers.','Digital modes')
add('Radio ID','','A numeric identifier used by some digital voice systems. Its assignment and format depend on the system. It does not replace the operator’s authorization or required station identification.','','Digital modes')
add('Talkgroup','','A logical group address used by digital voice systems to route or select conversations.','','Digital modes')
add('Colour code / time slot','','DMR settings: the colour code is a system access parameter, while a time slot selects one of two alternating traffic slots on a typical two-slot DMR repeater. Matching them alone does not ensure every other setting is correct.','','Digital modes')
add('D-STAR','Digital Smart Technologies for Amateur Radio','A digital voice and data system used on amateur radio. Uses callsign-oriented addressing and system-specific routing settings.','','Digital modes')
add('C4FM','Continuous four-level frequency modulation','A four-level digital modulation technique. In amateur radio it is associated with Yaesu System Fusion equipment; the modulation name and the complete system are different concepts.','','Digital modes')
add('APRS','Automatic Packet Reporting System','An amateur packet system for position reports, messages, telemetry and other real-time information. Its channels and operating practices depend on location.','','Digital modes')
add('AX.25','','A data-link protocol commonly used for amateur packet radio. Packets include addressing and error-detection information.','','Digital modes')
add('Packet radio','','Digital communication that sends data in structured packets. A modem converts between data and a radio-compatible signal.','','Digital modes')
add('FT8','','A narrow-band, time-synchronized digital mode used for weak-signal amateur contacts. It exchanges short structured messages rather than ordinary voice.','','Digital modes')
add('PSK / FSK','Phase-shift / frequency-shift keying','Digital modulation methods that encode information by changing phase or selecting different frequencies.','','Digital modes','modulation')
add('RTTY','Radioteletype','A text mode traditionally using frequency-shift keying and a teleprinter code.','','Digital modes')
add('CQ','','A general invitation for any station to reply. Listen first and make sure the frequency is available.','On HF: CQ CQ, this is [your assigned call sign].','Operating')
add('DX','','A distant station or long-distance contact. What counts as distant depends on the band and operating context.','','Operating')
add('QSO','','A radio contact or conversation between stations.','','Operating')
add('QRZ?','','Who is calling me? Also seen in the name of a callsign lookup service.','','Operating')
add('QRP','','Low-power operation. In contest contexts a common limit is 5 W output for CW, but definitions and categories vary.','','Operating')
add('QRT','','Stop transmitting or close down the station.','','Operating')
add('QSB','','Signal fading: received strength varies with time.','','Operating','propagation')
add('QRO','','Higher-power operation, or a request to increase transmitter power. Applicable limits still depend on authorization and band rules.','','Operating')
add('73','','A friendly amateur-radio closing meaning best regards.','','Operating')
add('Net','','An organized on-air meeting. A directed net has a net control station that coordinates participating stations.','','Operating')
add('NCS','Net control station','The station coordinating a directed radio net. Follow its instructions for check-in and traffic handling.','','Operating')
add('Call sign','','The station identifier assigned under the applicable radio authorization. In Canada, the required identification follows Canadian operating standards.','','Operating')
add('UTC','Coordinated Universal Time','The common time reference used for radio logs and scheduled contacts. Local daylight-saving changes do not change UTC.','','Operating')
add('Grid locator','','A compact geographical locator used for reporting station position, often using the Maidenhead system. It describes a grid area rather than an exact street address.','','Operating')
add('S-meter','','A receiver indication of signal strength. Calibration varies between radios, especially on VHF/UHF; the reading is not a universal precision power measurement.','','Measurements')
add('dBm','Decibels relative to one milliwatt','An absolute power level expressed on a logarithmic scale. 0 dBm is 1 mW; 30 dBm is 1 W.','A value in dBm is a power level. A value in dB alone normally describes a ratio.','Measurements','gain')
add('SWR','Standing-wave ratio','The ratio of maximum to minimum voltage along a line with a standing wave. It indicates mismatch relative to a stated reference impedance. A low SWR alone does not prove efficient radiation.','1:1 is a perfect impedance match. A dummy load can have low SWR while intentionally turning power into heat.','Antennas','antenna')
add('VSWR','Voltage standing-wave ratio','The voltage form of standing-wave ratio, often what an SWR meter or VNA reports.','','Antennas','antenna')
add('Return loss','','The reflected-power ratio expressed as a positive dB loss: larger return loss means less reflection and a better match.','A VNA may instead plot S11 magnitude in negative dB; a more negative value indicates less reflection.','Measurements','antenna')
add('S11 / S21','Scattering parameters','S11 describes input reflection. S21 describes forward transmission between two measurement ports under the stated reference conditions.','An antenna sweep commonly uses S11; a two-port filter test commonly uses S21.','Measurements','antenna')
add('Calibration plane','','The point in the measurement setup at which calibration defines the reference for the instrument’s readings.','Calibrate at the far end of a test cable when you want that cable removed from the antenna measurement.','Measurements','antenna')
add('50 ohms','','A common nominal impedance for radio connectors, coaxial feedlines and transceiver ports. It is not the same as measuring 50 Ω DC resistance across a length of coax.','','Antennas','antenna')
add('Coax','','Coaxial cable: an inner conductor surrounded by insulation and an outer conductor or shield. Frequently used as an unbalanced RF feedline.','','Antennas','gain')
add('Velocity factor','','The wave speed in a transmission line divided by the speed of light in vacuum. It relates electrical wavelength to physical line length.','At velocity factor 0.66, one wavelength in the cable is about 66% of its free-space length.','Antennas')
add('Unun','Unbalanced to unbalanced transformer','An impedance transformer between two unbalanced connections. Its ratio, power rating, bandwidth and common-mode behaviour depend on the design.','','Antennas')
add('Choke','','An impedance intended to impede unwanted current, often common-mode current on the outside of a coaxial shield. A choke and an impedance-transforming balun are not automatically interchangeable.','','Antennas')
add('Counterpoise / radials','','Conductors providing a return-current system for certain antennas, especially verticals. Their size and placement affect impedance and efficiency.','','Antennas')
add('Omnidirectional / omni','','Radiates or receives broadly in all azimuth directions under specified conditions. It is not equal radiation in every three-dimensional direction.','A vertical antenna may have an approximately doughnut-shaped pattern, with weak radiation off its ends.','Antennas')
add('Beamwidth / front-to-back ratio','','Beamwidth describes the angular width of a main lobe at a stated level, often half power. Front-to-back ratio compares radiation in the forward and opposite directions.','','Antennas')
add('Inductor / L','','A component that stores energy in a magnetic field and opposes changes in current. Its inductive reactance increases with frequency.','','Electronics','resonance')
add('Capacitor / C','','A component that stores energy in an electric field and opposes changes in voltage. Its capacitive reactance magnitude decreases with frequency.','','Electronics','resonance')
add('Resistance / reactance / impedance','','Resistance is the real part of impedance and dissipates average power. Reactance is the imaginary part and comes from energy storage. Impedance combines both.','An impedance of 50 + j30 Ω has 50 Ω resistance and +30 Ω inductive reactance.','Electronics','antenna')
add('Q factor','Quality factor','A measure associated with energy storage compared with loss in a resonator. Higher Q generally means narrower fractional bandwidth near resonance.','','Electronics','resonance')
add('RMS','Root mean square','An effective value of an alternating waveform used for power calculations. A sine wave’s RMS voltage is its peak voltage divided by √2.','','Measurements')
add('MUF / LUF','Maximum / lowest usable frequency','Path-dependent limits describing a usable HF propagation window under specified conditions. They change with ionization, absorption, noise and the chosen path.','','Propagation','propagation')
add('Skip zone','','An area between usable ground-wave coverage and the first returning sky-wave coverage where a particular path may not be received.','','Propagation','propagation')
add('Ionosphere','','Upper-atmosphere regions containing charged particles that affect radio propagation. Their density changes with sunlight and other conditions.','','Propagation','propagation')
add('Band edge','','The boundary of an allocated or authorized frequency band. The complete transmitted signal must fit within the applicable limits.','','Operating')
add('AC / DC','Alternating current / direct current','AC changes direction periodically. DC maintains one direction, though its value can still vary. A typical radio power supply converts mains AC into low-voltage DC.','','Electronics','ohm')
add('Volt / V','','The unit of electric potential difference. Voltage can drive current through an impedance.','13.8 V DC is a common nominal supply for equipment designed for a 12 V vehicle electrical system.','Units','ohm')
add('Ampere / A','','The unit of electric current: the rate of electric charge flow.','A radio requiring 10 A needs a suitable supply, wiring and protection for that load.','Units','ohm')
add('Ohm / Ω','','The unit of resistance and impedance. Ohm’s law relates voltage, current and resistance in a resistor.','12 V across 6 Ω gives 2 A.','Units','ohm')
add('Watt / W','','The unit of power, or energy transferred per second. For a DC load, P = VI.','A 12 V load drawing 2 A consumes 24 W. RF output power and supply input power are different measurements.','Units','ohm')
add('Hertz / Hz','','The unit of frequency, equal to one cycle per second.','1 MHz = 1,000,000 Hz. A 100 Hz CTCSS tone is an audio signalling frequency, not the radio’s VHF carrier frequency.','Units','wavelength')
add('Metric prefixes','','Prefixes express powers of ten: pico (p) = 10⁻¹², nano (n) = 10⁻⁹, micro (µ) = 10⁻⁶, milli (m) = 10⁻³, kilo (k) = 10³, mega (M) = 10⁶ and giga (G) = 10⁹.','1 µF = 1,000 nF = 1,000,000 pF. Uppercase M and lowercase m differ by a factor of a billion.','Units')
add('Farad / F','','The unit of capacitance. Radio tuned circuits often use picofarads (pF), while power-supply capacitors may use microfarads (µF).','','Units','resonance')
add('Henry / H','','The unit of inductance. RF coils commonly use microhenries (µH) or nanohenries (nH).','','Units','resonance')
add('Ohm’s law','','For a resistor, voltage equals current multiplied by resistance: V = IR. Use consistent units.','At 12 V with 100 Ω, I = 0.12 A and resistor heat is 1.44 W.','Electronics','ohm')
add('Series / parallel','','Series components share one current path. Parallel components connect across the same two nodes and share the same voltage.','Two 100 Ω resistors in series give 200 Ω; in parallel they give 50 Ω.','Electronics','ohm')
add('Open / short circuit','','An open circuit breaks the current path. A short circuit is an unintended or deliberately very low-impedance connection that can allow excessive current.','An open switch stops current; a short across a battery can create a high fault current.','Electronics')
add('Conductor / insulator','','A conductor permits charge flow readily; an insulator resists it under the intended conditions. Real materials and insulation have limits.','','Electronics')
add('Diode','','A semiconductor component that conducts much more readily in one direction than the other. Used for rectification, switching and signal detection.','','Electronics')
add('Transistor / FET','Transistor / field-effect transistor','Semiconductor devices used for amplification or switching. In a bipolar transistor, base drive controls collector current; in a FET, gate voltage controls conduction.','','Electronics')
add('Resistor colour code','','A system of coloured bands indicating resistance and tolerance. Band count changes how many significant digits are used.','For a four-band resistor: first two bands are digits, third is a multiplier, fourth is tolerance.','Electronics')
add('Transformer','','Transfers energy between magnetically coupled windings. The turns ratio sets ideal voltage transformation and the square of that ratio relates impedances.','A 2:1 voltage turns ratio corresponds to a 4:1 impedance ratio.','Electronics')
add('Rectifier / regulator','','A rectifier changes AC into unidirectional current. A regulator maintains a desired output voltage within its operating limits. Filters reduce ripple.','','Electronics')
add('Fuse / circuit breaker','','A protective device that interrupts a circuit under specified overcurrent conditions. Its rating and placement must suit the wiring and equipment.','A fuse is not a guarantee against electric shock; never substitute a larger fuse to hide a fault.','Safety')
add('Ground / bonding','','Grounding provides connections to the applicable reference or earth system. Bonding joins conductive parts to reduce dangerous voltage differences. Safety ground, lightning protection and RF return paths have different functions and require appropriate design.','','Safety')
add('Safety Code 6','','Health Canada’s radiofrequency exposure guidance. Station assessment must account for power, frequency, antenna characteristics, duty cycle and where people can be located.','A low SWR reading is not an RF-exposure assessment.','Safety')
add('Duty cycle','','The fraction of time a transmitter or component is active over a stated interval. Thermal and exposure assessments depend on the relevant duty cycle.','A steady digital transmission may heat a transmitter differently from intermittent speech at the same peak setting.','Safety')
add('Oscillator','','Produces a repeating electrical waveform. A radio uses oscillators to generate carriers, frequency references and local signals for conversion.','','Electronics')
add('Mixer','','Combines signals in a nonlinear circuit to produce sum and difference frequency components. A receiver selects the desired component using filters.','A 14 MHz input mixed with a 9 MHz oscillator can produce components at 5 MHz and 23 MHz.','Electronics')
add('Detector / demodulator','','Recovers the information carried by a modulated signal. Different modes require appropriate demodulation.','','Electronics','modulation')
add('Superheterodyne','','A receiver architecture that converts the tuned signal to one or more intermediate frequencies before demodulation.','','Electronics')
add('Filter','','Passes some frequencies while attenuating others. Low-pass, high-pass, band-pass and band-reject describe different responses.','A low-pass filter may reduce transmitter harmonics above its passband.','Electronics')
add('Spurious emission','','An unwanted transmitted signal outside the intended emission, including certain harmonics and mixing products. Good transmitter design, adjustment and filtering help suppress it.','','Interference')
add('Splatter / key clicks','','Unwanted bandwidth caused by effects such as transmitter overdrive or abrupt waveform changes. Splatter is often associated with distorted speech modulation; key clicks with excessively abrupt CW keying.','','Interference','modulation')
add('Overload / desensitization','','Overload occurs when a signal exceeds a receiver stage’s useful linear range. Desensitization is a loss of ability to hear weak signals, often in the presence of strong signals.','An attenuator can sometimes improve reception near very strong transmitters.','Interference')
add('Decibel / dB','','A logarithmic ratio. For power, dB = 10 log10(P₂/P₁). About +3 dB doubles power and −3 dB halves it. Voltage ratios use 20 log10 only under appropriate equal-impedance conditions.','','Measurements','gain')
add('SINAD','Signal plus noise plus distortion to noise plus distortion','A receiver-quality measurement often used when specifying analogue FM sensitivity. The test conditions and bandwidth matter when comparing radios.','','Measurements')
add('Tuning / matching','','Tuning can mean adjusting a radio’s frequency or changing antenna resonance. Impedance matching transforms a load to a desired input impedance. Antenna resonance and a 50 Ω match are related but distinct goals.','A resonant 100 Ω antenna has no reactive component at resonance, but its SWR on a 50 Ω line is 2:1.','Antennas','antenna')
add('Radiation efficiency','','The fraction of power accepted by an antenna that becomes radiated electromagnetic energy rather than loss. It is distinct from feedline loss and impedance mismatch.','A good match can still feed a very inefficient antenna.','Antennas','gain')
add('Feed point','','The point where a transmission line connects to an antenna. Feed-point impedance depends on the antenna and installation.','','Antennas','antenna')
add('Quarter-wave / half-wave','','Electrical lengths equal to one-quarter or one-half of a wavelength. Actual element length depends on end effects, geometry and surrounding materials.','The wavelength lab compares free-space fractions with approximate practical wire lengths.','Antennas','wavelength')
add('VHF / UHF','Very high frequency / ultra high frequency','VHF spans 30–300 MHz and UHF spans 300–3,000 MHz. These are frequency-region names; amateur allocations occupy particular parts of them.','','Units','wavelength')
add('HF','High frequency','The 3–30 MHz frequency region. Several amateur bands lie here, and ionospheric propagation can support long-distance contacts.','The 14 MHz amateur band is in HF.','Units','propagation')
add('ITU','International Telecommunication Union','The United Nations specialized agency coordinating international telecommunications matters, including international radio allocations and regulations. Canadian authorization still comes through Canadian rules.','','Canadian certification')
add('ISED','Innovation, Science and Economic Development Canada','The federal department responsible for Canadian amateur radio certification and spectrum management.','','Canadian certification')
add('RIC / RBR','Radiocommunication Information Circular / Regulation by Reference','ISED publication designations. RIC-3 describes amateur qualifications and syllabus information; RBR-4 contains amateur operating standards. Read current official versions when making operating decisions.','','Canadian certification')
add('Basic Qualification','','The entry Canadian amateur radio qualification. The Basic examination has 100 multiple-choice questions and a 70% pass mark. A new Basic-only result below 80% generally limits frequency access to amateur allocations above 30 MHz.','','Canadian certification')
add('Basic with Honours','','Basic examination achievement at 80% or higher, granting the additional frequency privileges specified by Canadian rules, including amateur allocations below 30 MHz. It does not by itself become the Advanced Qualification.','','Canadian certification')
add('Advanced Qualification','','An additional Canadian amateur qualification associated with further technical and operating privileges. This app prepares for the Basic examination, with Honours as a study goal.','','Canadian certification')
for g in terms.values():
    g.setdefault('expansion','');g.setdefault('example','');g.setdefault('category','Concepts');g.setdefault('lab','');g.setdefault('source','')
c['glossary']=sorted(terms.values(),key=lambda g:g['term'].casefold())
c['glossary_sources']=[{'title': 'Retevis RT95 manufacturer manual · OWNID', 'url': 'https://www.radiomanual.info/schemi/Vari/Retevis_RT-95_user.pdf', 'publisher': 'Retevis', 'publisher_url': 'https://www.retevis.com/', 'host': 'RadioManual.info'}, {'title': 'Retevis · OwnID and DTMF selective calling', 'url': 'https://www.retevis.com/blog/ra89-dtmf-function-operation-steps', 'publisher': 'Retevis'}, {'title': 'Kenwood · Radio terminology glossary', 'url': 'https://comms.kenwood.com/en/support/glossary/', 'publisher': 'KENWOOD'}, {'title': 'Icom · VOX function', 'url': 'https://www.icomjapan.com/lineup/products/3377/', 'publisher': 'Icom Inc.'}, {'title': 'Icom · IC-T10 product reference', 'url': 'https://www.icomjapan.com/lineup/products/IC-T10/', 'publisher': 'Icom Inc.'}]
